let depth = 0, maxDepth = 0, calls = 0;
function f(n) {
  calls++;
  depth++;
  maxDepth = Math.max(maxDepth, depth);
  if (n > 0) {
    f(n - 1);
    f(n - 1);
  }
  depth--;
}
